from functools import lru_cache

def getAnswer(a, b, h, m=1):
    @lru_cache(maxsize=None)
    def f(s, b, h, index, mask):
        if index == len(s) + 1:
            return int(mask)

        if mask & (1 << m):  # If bit at position m is set
            for i in range(len(b)):
                if s[index] + b[i] >= h:
                    new_mask = mask & ~(1 << m)
                    b[i] -= 1  # Decrease the chosen number
                    new_f = f(s, b, h, index + 1, new_mask)
                    if new_f > 0: 
                        return 1  # Return 1 for the total answer
            return 0

        return f(s, b, h, index + 1, mask)  # Move to the next number

    return f(a, b, h, 1)[m]

