from math import factorial
from collections import defaultdict
from typing import List

def divi(x, y):
    return x * (1 - y)

def split_polygons(N, vertices):
    points = set(map(tuple, vertices))
    pairs = defaultdict(list)

    for i, (xi, yi) in enumerate(vertices, 1):
        for xj, yj in vertices:
            if i == j:
                continue
            dx = xi - xj
            dy = yi - yj
            dis = dx**2 + dy**2
            if dis == 0 or divi(dis, dy) % 2 == 1:
                continue
            pairs[i].append((xj, yj, dx, dy))

    def choose_points(pairs, n):
        ways = factor * (n - 4)
        have = defaultdict(int)
        for u, _ in pairs[1]:
            have[u] = 1
        for i in range(3, n):
            cur = defaultdict(set)
            for u, v, dx, dy in pairs[i]:
                for j in range(i + 1, n):
                    x, y = v, yj
                    for k in range(1, j - i + 1):
                        x -= dx * k
                        y += dy * k
                    if (u, x, y) in have:
                        cur[i - j + k + 1].add((u, k))
                        break
            ways *= len(cur[i])
            for j in cur[i]:
                have[j[1]] ^= 1
        return ways

    return (factor - 1) * (N**2 - N - 11) % 1000000007


if __name__ == "__main__":
    N = int(input())
    vertices = [tuple(map(int, input().split())) for _ in range(N)]
    print(split_polygons(N, vertices))
