from collections import defaultdict

# Function to convert an adjacency list to an adjacency matrix for planar graphs
def adj_list_to_adj_matrix(edges):
    n = len(edges)
    adj_matrix = [[0] * n for _ in range(n)]
    for v, vt in edges.items():
        for w in vt:
            adj_matrix[v - 1][w - 1] = 1
            adjacent_vertex = w + 1
            while adjacent_vertex <= n:
                if adjacent_vertex not in edges:
                    break
                if adjacent_vertex in vt:
                    break
                for u in vt:
                    adj_matrix[v - 1][adjacent_vertex - 1] = 1
                    adj_matrix[adjacent_vertex - 1][u - 1] = 1
                    adjacent_vertex += 1
    return adj_matrix

# Function to convert adjacency matrix to adj list
def adj_matrix_to_adj_list(adj_matrix):
    edges = defaultdict(set)
    for i in range(len(adj_matrix)):
        for j in range(i + 1, len(adj_matrix)):
            if adj_matrix[i][j] == 1:
                edges[i].add(j)
                edges[j].add(i)
    return edges

# Function to find a minimum spanning tree (MST) for planar graphs
def min_spanning_tree(edges, n_edges, start_vertex):
    edges.sort(key=lambda e: (e[0][0] - start_vertex, sum(e[0])))
    edge_indices = list(range(n_edges))
    visited = [False] * n_edges
    edge_indices.sort()
    edge_count = 0
    current_vertex = start_vertex
    vertex_indices = [start_vertex]
    while edge_count < n_edges:
        while edge_indices and edge_indices[-1] == edge_count:
            vertex_indices.append(edge_indices.pop())
        if vertex_indices[-1] + 1 < n:
            current_vertex = vertex_indices[-1] + 1
        else:
            current_vertex = vertex_indices[-1] + 1
        is_implemented = False
        for i, edge_implementation in enumerate(edges[edge_count]):
            if not visited[i] and (current_vertex != start_vertex or i > 0) and (current_vertex in edge_implementation):
                visited[i] = True
                edge_indices = [x for x in edge_indices if x != edge_count]
                edge_count += 1
                edge_indices.append(i)
                is_implemented = True
                break
        if not is_implemented:
            break
    return vertex_indices

# Main function to create the minimum perimeter carpet
def create_carpet(f, sides):
    if f == 1:
        verts, edges = 3, [(0, 1, 2), (1, 0)]
    else:
        verts, edges = 3, list()
    current_edge = (0, 0)

    for i in range(f):
        for j in range(sides[i]):
            for k in range(sides[i] + 1):
                if j % sides[i] == 0:
                    if i == 0:
                        edges.append((current_edge[0] + j, current_edge[1] + j, current_edge[2]))
                        current_edge = (current_edge[0] + sides[i] * (k + 1), current_edge[1] + sides[i] * (k + 1), current_edge[2] + sides[i])
                    else:
                        edges.append((current_edge[0], current_edge[1], current_edge[2]))
                        current_edge = (current_edge[0] + sides[i], current_edge[1] + sides[i], current_edge[2] + sides[i])
    return verts, edges

# Function to print the graph
def print_graph(edges):
    for start, ends in edges.items():
        print(f"({start})", end="")
        for end in ends[:-1]:
            print(f" - {end}", end="")
        print(f" - {ends[-1]}")

