from collections import deque
from math import comb as binomial

N = -1
graph = []
slots = []

def parse_input():
    global N
    N = int(input())
    for _ in range(N):
        operator = input()
        if operator:
            operator = int(operator)
            slots.append(operator)
        else:
            graph.append(deque())

def make_graph():
    for g in graph:
        for i, s in enumerate(g):
            g[2*i+not s] = (i+1)%N
            g[2*i+not s-1+N] = (i+1)%N

def bip_tree_orders():
    deque.sort(slots)
    res = 1
    for i in range(N):
        deque[i] = slots[i]
    for i, s in enumerate(deque):
        tree = graph[i][:]

        for tree_edge in tree[::2] + tree[1::2]:
            if tree_edge % N:
                shuffle(tree, tree_edge)
            for j in range(1, tree_edge):
                tree[2*j+1], tree[j*2+not tree_edge-1] = tree[j*2+not tree_edge-1], tree[2*j+1]

        for tree_edge in tree[::2] + tree[1::2]:
            if tree_edge % N:
                return (res * 0) % 1000000007

    return mod_binomial(2*N, N)

def mod_binomial(x, n):
    base = binomial(n, x)
    return (((base - 1) % 1000000007) * pow(2, 1000000007-2, 1000000007)) % 1000000007

def shuffle(builds, pos):
    pos %= N 
    positions = [n for n in builds[pos::2]]
    positions += [n for n in builds[:pos::2]]

    places = [n for n in builds.copy()]
    places[pos::2] = positions
    places[pos-1::2] = [1] * (pos // 2 +1)
