def find_shortest_path(start, end, graph):
    queue = deque([(start, [start])])
    visited = set([start])
    min_path = float('inf')
    while queue:
        current_node, path = queue.popleft()
        if current_node == end:
            min_path = min(min_path, len(path))
        for neighbor in graph[current_node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    return min_path

def count_shortest_path_passes(graph, edges):
    shortcut = 0
    unvisited_shortcuts = []
    for i in range(2, len(edges) + 1):
        path_length = find_shortest_path(1, i, graph)
        if path_length == i - 1:
            shortcut += i - 1
            unvisited_shortcuts.append(i)
    for edge in unvisited_shortcuts:
        shortcut += find_shortest_path(edge - 1, edge, graph)
        shortcut += graph[edge].count(edge)
    return shortcut

