from itertools import combinations

def transform_graph_to_tension(graph):
    graph = {(u, d): graph[u][d] + graph[d][u] for u, d in graph}
    pairs = {tuple(c) for c in combinations(graph, 2)} | {tuple((u, u)) for u in graph}
    weights = {(u, d): graph[u, d] for u, d in pairs}
    tensions = {c: u for u, c in graph.items()}  # tension map for tension problem
    return weights, tensions

def hungarian_algorithm(tonic_problem):
    tensions = tonic_problem[0]
    tensions = {c: 1 if c in (u, d) for u, d in tensions and u != d}
    m = tensions.values()
    w = tensions.keys()
    for v1 in w:
        for v2 in w:
            tensions[(v1, v2)] -= sum(tonic_problem[1][c] for c in (v1, v2))
    return list(tensions.keys())

def add_cables(graph, directions, n):
    for _ in range(n - len(directions)):
        paired = {k for k, v in graph.items()}
        edges = list(paired - set((u, v)) for u, v in combinations(graph, 2))
        for u, v in (u, v) for u, v in combinations(paired - set((v, u)), 2):
            if u < v:
                graph[u, v] = directions[(u, v)]
            else:
                graph[v, u] = directions[(u, v)]
        directions = directions | edges

