from typing import List

def hamming_distance(a: str, b: str) -> int:
    """Return the Hamming distance between two strings."""
    return sum(c1 != c2 for c1, c2 in zip(a, b))

def find_strings(h1: int, h2: int, h3: int, h4: int) -> List[str]:
    """Find four strings with the given pairwise Hamming distances."""
    # The minimum length string for each pair starting with distance h1
    min_length = h1 + 1
    # The minimum length of the fourth string
    length = h1 + h3 + 1
    # Checking if such strings exist based on given distances
    found = all(min_length >= h1 and length >= h2 and length >= h3 and length + h4 >= h3 and length + h4 - h3 >= h1 for h1, h2, h3, h4 in [(h1, h2, h3, h4), (h1, h2, h3 + 1, h4), (h1, h2 + 1, h3, h4), (h1 + 1, h2, h3, h4)])
    if not found:
        return [-1]
    result = [""] * 4
    strings = ["a" * 2]
    while h4 >= 2:
        i = h4 - 2
        j = h2 + h1 + 1
        if h2 + h1 < h1 + h3:
            h4 -= 1
            for s in strings:
                s = s[:i] + 'b' + s[i:]
                if hamming_distance(result[j], s) == h4:
                    result[j] = s
        else:
            h4 -= 1
            for s in strings:
                s = s[:j] + 'a' + s[j:]
                if hamming_distance(result[i], s) == h4:
                    result[i] = s
    return result

