def count_ways(n):
    ways = 0
    for perm in permutations((1,)+([0]*n)+([-1,]*n)):
        if is_valid_polygon(perm):
            ways += 1
    return ways % 1000000007

def is_valid_polygon(order):
    prev = order[0]
    for i in range(len(order)):
        curr = order[(i+1)%len(order)]

        # Check if the two points are on the same line
        if complex(prev), complex(curr) == complex(prev.imag, -prev.real) == complex(curr.imag, -curr.real):
            return False

        prev = curr

    if not is_collinear(order[1], order[2], order[3]) and not is_collinear(order[2], order[3], order[1]) and not is_collinear(order[3], order[1], order[2]):
        return False

    if complex(order[1]), complex(order[3]) == complex(order[1]+1, -order[1].real) and not is_collinear(order[1], order[3], order[2]):
        return False

    return True

def is_collinear(a, b, c):
    cross_product = (a.imag + 1) * (c.imag - b.imag) - (a.real + 1) * (c.real - b.real)
    return abs(cross_product) <= 0.001

