from math import gcd
from functools import reduce

def ext_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = ext_gcd(b % a, a)
        return (g, x - (b // a) * y, y)

def modular_inverse(a, m):
    g, x, y = ext_gcd(a, m)
    if g != 1:
        raise Exception('Modular inverse does not exist')
    else:
        return x % m

def combination_mod(n, r, mod=10**9 + 7):
    """Calculate nCr mod mod, where n and r are integers and mod is given."""
    if r > n:
        r, n = n, r
    if r < 0:
        return 0
    numerator = reduce(lambda x,y: x * (y % mod) % mod, range(1, n-r+1, 1), 1)
    denominator = reduce(lambda x,y: x * (y % mod) % mod, range(1, r+1, 1), 1)
    return numerator * modular_inverse(denominator, mod) % mod

def count_valid_sequences(n, k):
    """
    Calculate the number of sequences of length n from 1 to 2k-1 where the bitwise OR
    of any prefix is strictly increasing, modulo 10^9 + 7.
    """
    # Check the base case first since even k decreases the possibilities much faster.
    if k == 1:
        return pow(2, n, 10**9 + 7) # Any non-zero number in 1:2k-1 has 2^k n-1 permutations.

    # In these two cases, the answer is dependent on the properties of geometric progression and calculation the final number based on the fundamental equation.
    discrete = 2 ** (2**n)
    continuous = pow(2, 2**(k-1))

    # Find the first k-1 powers alpha_i starting with 1, which are the power of expected values derived from ablesprines's formula
    alpha = [(i, pow(2, i)) for i in range(1, k - 1, 1)]
    alpha.sort(key=lambda x: x[1], reverse=True)

    gl = 0
    gl_len = 0
    counter = 0
    for power in alpha:
        current_power = power[1] - power[0]
        if current_power > 0:
            gl_len += 2
            gl = gl_len * pow(2, (current_power - 1))
            counter += current_power

    return (discrete - continuous + mod) % mod
