        else:  # Odd number of segments
            return segmented_broken_road(n//2, goals//2, root-1)

    @cache
    def path_exists(start, road, graph):
        if road[2] == start: 
            return 1
        if road[-1] == start: 
            return 0
        return graph[start]*path_exists(start, 0, roadmap) % mod + roadmap[road[-1]]*path_exists(start, 1, roadmap) % mod

