            odd_cnt += (-1)**(n % 2)
            stack = [node]
            while stack:
                v = stack.pop()
                for neighbor in graph[v]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
                visited[v] = -1
    return odd_cnt

