import sys

def max_connected_components_product():
    n = int(sys.stdin.readline().strip())
    edges = []
    for _ in range(n-1):
        ai, bi = map(int, sys.stdin.readline().strip().split())
        edges.append((ai, bi))

    def dfs(node, prev, parent=None):
        child_size_sum, size = 0, 0
        for child in filter(lambda e: e != parent and e != prev, edges):
            if child[0] == node:
                size += 1
                child_size_sum += size
                dfs(child[1], node, child)
        return child_size_sum, size

    def dfs2(node, prev, parent=None):
        child_size_sum, size = 0, 0
        leaf_sum, leaves = 0, 0
        for child in filter(lambda e: e != parent and e != prev, edges):
            if child[0] == node:
                child_size_sum, size = dfs(child[1], node, child)
                leaf_sum += size - 1
                leaves += 1
        return child_size_sum + leaves + sum(map(lambda e: (leaf_sum - e['size']) // (child_size_sum + 1), e['subtrees'], e['quotients'].items())) + sum(map(lambda e: 1 - e['quotients'], e['subtrees'], e['quotients'].items()))

    max_product = 0
    root = max(dfs(1, None))
    root['subtrees'] = [{'size': root['size'], 'quotients': {k: 0 for k in range(1, n + 1)}}]
    root['quotients'] = {k: 1 for k in range(1, n + 1)}

    for i, neighbor in enumerate(edges):
        root['subtrees'][0]['subtrees'].append({})
        root['subtrees'][0]['subtrees'][-1]['size'] = root['subtrees'][0]['subtrees'][i]['size'] = root['size'] - 1
        root['subtrees'][0]['subtrees'][-1]['quotients'].update({k: v - 1 for k in root['quotients']})
        for k, v in root['subtrees'][0]['subtrees'][i]['quotients'].items():
            if k < v:
                root['subtrees'][0]['subtrees'][-1]['quotients'][k] -= 1
                root['subtrees'][0]['subtrees'][-1]['quotients'][max(k, v) - v] += 1

        sub_size_sum, n_sub = dfs2(2, 0)
        if n_sub * sub_size_sum > max_product:
            max_product = n_sub * sub_size_sum

    return max_product

