from collections import defaultdict

def build_tree(edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    return graph

def calc_roots(graph):
    def dfs(node, parent):
        seen.add(node)
        for child in graph[node]:
            if child != parent:
                dfs(child, node)
        return seen

    seen = set()
    roots = []
    for node in graph:
        if node not in seen and len(dfs(node, None)) > 1:
            root = node
            seen = bases[node]
            roots.append(root)
    return roots

def count_uniq_paths(graph):
    def dfs(node, parent):
        seen.add(node)
        for child in graph[node]:
            if child != parent:
                vis[node].add(child)
                vis[child].add(node)
                dfs(child, node)
        return seen

    bases = defaultdict(set)
    seen = set()
    for node in graph:
        if node not in seen and len(dfs(node, None)) == 1:
            node_root = node
            original_node = node
            while node_root not in bases:
                node_root = bases[node_root]
            for child in graph[original_node]:
                child_root = bases[original_node]
                while child != child_root:
                    vis[child] = set(child_root)
                    vis[child_root] = set(child)
                    node_root = child_root
                    child_root = bases[node_root]
                bases[node].add(node_root)
                node_root = node_root

    all_map = defaultdict(lambda: set())
    for node in graph:
        for child in graph[node]:
            if child not in vis[node]:
                vis[node].add(child)
                all_map[node].add(child)

    return sum([len(ld) + 1 - len(bases[ld]) for ld in vis if len(bases[ld]) == 0] + [1])

def gather_data(n, lis, edges):
    graph = build_tree((l, r) for l, r in edges)
    return graph, lis

def answer(n, lis, graph, edges):
    nums = [lis[i-1] for i in range(1, n+1)]
    roots = calc_roots(graph)
    unique_count = count_uniq_paths(graph)
    return nums[roots[0]-1], unique_count

