from collections import defaultdict, deque

def clockwise(start, end):
    start, end = max(start, end), min(start, end)
    return (start + end) % 3, (start + 3 - end) % 3 == 1

def deque_list(deck):
    stack, res = [], []
    while deck:
        stack.append(deck.popleft())
    while stack:
        res.append(stack.pop())
    return res

def optimize_cables(computer_count, cable_count, cables):
    connecting_directions = set()
    for a, b in cables:
        connect = clockwise(a, b)
        d1, d2 = connect
        connecting_directions.add((d1, d2))
    phone_count = computer_count + 2 * cable_count
    cabling = [[0] * phone_count for _ in range(phone_count)]
    for d1, d2 in connecting_directions:
        for a in range(phone_count):
            for b in range(a + 1, phone_count):
                if cabling[(a, b)][d1] == 2 or cabling[(a, b)][d2] == 2:
                    diff = clockwise(min(a, b), max(a, b))
                    cabling[(a, b)][diff] = 1
    res = deq_of_sp(var.findAllConnectedEdges(checkMap=cabling))
    res.append([(b, l) for l in res])
    res = addrsOrListOfEdge(res)
    res = sorted(res, key=lambda (a, b): (a, b))
    return cabling, res
