def count_cinema_arrangements(n, indices, known_positions):
    occupied_slots = [(i, -1, -1) for i in range(n)]
    for i, pos in enumerate(indices, 1):
        occupied_slots[i-1] = pos, i-1, i+1

    dp = {0: 1, 1: 1}

