        for j in range(i-1, -1, -1):
            if i-1 >= 0:
                occupied_slots[i] = max(occupied_slots[i], occupied_slots[i-1])
            occupied_slots[i][2] = j if j >= 0 else -1
            dp[i+1] = (dp[i+1] + dp[j]) % 1000000007

    return dp[n]

