def count_ways(n, vertices):
    dp = [1] + [0] * n
    for i in range(1, n):
        for j in range(max(0, i-3), i):
            if dp[j] + (vertices[i][0] - vertices[j][0]) * (vertices[i][0] - vertices[j][1]) <= vertices[i][0] * vertices[i][1] - vertices[j][0] * vertices[j][1] + MOD:
