from functools import cache
from itertools import product

def calculate_truncated_lcs(n, m, s):
    # Build the initial DP table for LCP lengths
    lcp_dp = [[-1] * m for _ in range(n)]
    lcp_dp[0][s[0] - 'a'] = 0

    for i in range(n - 1):
        for j in range(m):
            if s[i + 1] == chr(ord('a') + j):
                if i >= 1 and lcp_dp[i][j] >= 0:
                    lcp_dp[i + 1][j] = lcp_dp[i][j] + 1
                break

    # Calculate truncated LCP counts
    truncated_lcp_count = 0
    for left_row in range(1, n):
        longest_matching_row = -1
        for column in range(m):
            if lcp_dp[left_row][column] >= 0:
                if longest_matching_row == -1:
                    longest_matching_row = lcp_dp[left_row][column]
                elif lcp_dp[left_row][column] > longest_matching_row:
                    longest_matching_row = lcp_dp[left_row][column]

            if longest_matching_row == n - 1:
                truncated_lcp_count += 1

    return truncated_lcp_count

